fn coverage_to_alpha(px: &mut [u32], fg: (u8, u8, u8)) {
    for p in px.iter_mut() {
        let a = ((*p >> 16) & 0xFF).max((*p >> 8) & 0xFF).max(*p & 0xFF);
        let pm = |c: u8| (c as u32 * a + 127) / 255;
        *p = a << 24 | pm(fg.0) << 16 | pm(fg.1) << 8 | pm(fg.2);
    }
