/// the shell to open the app, which does the same for a running one.
pub fn activate(id: &str) {
    let ff_folders = firefox_folders(id);
    struct Search<'a> {
        id: &'a str,
        ff: &'a [String],
        found: Option<HWND>,
    }
    unsafe extern "system" fn each(h: HWND, lp: LPARAM) -> BOOL {
        let s = &mut *(lp.0 as *mut Search);
        let visible = IsWindowVisible(h).as_bool();
        let owned = GetWindow(h, GW_OWNER).is_ok_and(|o| !o.is_invalid());
        let titled = GetWindowTextLengthW(h) > 0;
        let tool = (GetWindowLongW(h, GWL_EXSTYLE) as u32 & WS_EX_TOOLWINDOW.0) != 0;
        if visible && !owned && titled && !tool && belongs(h, s.id, s.ff) {
            s.found = Some(h);
            return FALSE;
        }
        TRUE
    }
    let mut search = Search { id, ff: &ff_folders, found: None };
    unsafe {
        let _ = EnumWindows(Some(each), LPARAM(&mut search as *mut _ as isize));
        match search.found {
            Some(h) => {
                if IsIconic(h).as_bool() {
                    let _ = ShowWindow(h, SW_RESTORE);
                }
                let _ = SetForegroundWindow(h);
            }
            None => {
                let target = wide(&format!("shell:AppsFolder\\{id}"));
                ShellExecuteW(None, windows::core::w!("open"), PCWSTR(target.as_ptr()), None, None, SW_SHOWNORMAL);
            }
        }
    }
}

