/// Paints a brand colour at `alpha` (0..1) under what's in the strip's buffer, in the hover
/// highlight's shape (`radius`, `inset` from top and bottom), so text and icons stay on top.
fn tint_under(buf: &mut [u32], width: i32, height: i32, (r, g, b): (u32, u32, u32), alpha: f32, radius: f32, inset: i32) {
    let (x0, y0, x1, y1) = (0.0f32, inset as f32, width as f32, (height - inset) as f32);
    for y in inset.max(0)..(height - inset).min(height) {
        for x in 0..width {
            let (fx, fy) = (x as f32 + 0.5, y as f32 + 0.5);
            let (cx, cy) = (fx.clamp(x0 + radius, x1 - radius), fy.clamp(y0 + radius, y1 - radius));
            let cover = (radius - ((fx - cx).powi(2) + (fy - cy).powi(2)).sqrt() + 0.5).clamp(0.0, 1.0);
            let ta = alpha * cover;
            if ta <= 0.0 {
                continue;
            }
            let p = &mut buf[(y * width + x) as usize];
            let a = (*p >> 24) as f32 / 255.0;
            let under = ta * (1.0 - a); // only where the strip's own pixels don't cover
            let ch = |s: u32, c: u32| ((((*p >> s) & 0xff) as f32 + c as f32 * under).round() as u32).min(255) << s;
            let na = ((a + under) * 255.0).round().min(255.0) as u32;
            *p = na << 24 | ch(16, r) | ch(8, g) | ch(0, b);
        }
    }
}

