/// the frame timer runs while it moves.
fn feel_update() {
    let Some((main, run, was)) = with(|a| {
        let on = a.hover == Some(Part::Cover);
        a.feel.set(on, on && a.pressed == Some(Part::Cover));
        if !a.look.animations {
            a.feel.snap();
        }
        (a.main, a.feel.animating(), std::mem::replace(&mut a.feeling, a.feel.animating()))
    }) else { return };
    if run && !was {
        unsafe { SetTimer(main, TIMER_FEEL, taskbar_dock::anim::FEEL_FRAME_MS, None); }
    }
    redraw_strip();
}

