/// A highlight box over columns `span` = (left, right) in `rgb24` (a Discord colour) at `alpha`
/// (0..255), under the strip's pixels like `draw::background_in`'s but tinted: same shape
/// (`radius`, `inset` from top and bottom), anti-aliased.
#[allow(clippy::too_many_arguments)]
fn tint_highlight(buf: &mut [u32], width: i32, height: i32, span: (i32, i32), rgb24: u32, alpha: f32, radius: f32, inset: i32) {
    let shape = (span.0 as f32, inset as f32, span.1.min(width) as f32, (height - inset) as f32);
    let tint = (rgb24 >> 16 & 0xff, rgb24 >> 8 & 0xff, rgb24 & 0xff);
    for y in 0..height {
        for x in span.0.max(0)..span.1.min(width) {
            let cover = draw::shape_cover(x as f32 + 0.5, y as f32 + 0.5, shape, radius);
            let ba = (alpha * cover).round() as u32;
            if ba == 0 {
                continue;
            }
            let p = &mut buf[(y * width + x) as usize];
            let (a, inv) = (*p >> 24, 255 - (*p >> 24));
            let ch = |shift: u32, t: u32| ((*p >> shift) & 0xff) + t * ba / 255 * inv / 255;
            *p = (a + ba * inv / 255) << 24 | ch(16, tint.0) << 16 | ch(8, tint.1) << 8 | ch(0, tint.2);
        }
    }
}

