        if let Some(to) = bar_width(compact) {
            let lk = look();
            if motion(|m| m.resize(from, to, &lk, Instant::now())) {
                timer(TIMER_RESIZE, true);
            }
        }
    }
    motion(|m| m.resize_width())
}

